{
  "type": "object",
  "name": "AccessRequest",
  "properties": {
    "requester_email": {
      "type": "string",
      "description": "Email of the user requesting access."
    },
    "proposer_email": {
      "type": "string",
      "description": "Admin who proposed the grant on someone's behalf \u2014 full_admin/breakglass approvals must come from a DIFFERENT admin."
    },
    "requested_sections": {
      "type": "array",
      "description": "Admin sections requested \u2014 empty means full admin.",
      "items": {
        "type": "string"
      }
    },
    "reason": {
      "type": "string",
      "description": "Why access is needed (free text)."
    },
    "status": {
      "type": "string",
      "enum": [
        "pending",
        "approved",
        "rejected"
      ],
      "default": "pending"
    },
    "reviewer_email": {
      "type": "string"
    },
    "decided_at": {
      "type": "string",
      "format": "date-time"
    },
    "decided_note": {
      "type": "string"
    }
  },
  "required": [
    "requester_email",
    "status"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "AccountDeletionRequest",
  "type": "object",
  "description": "Persistent user-requested account deletion review. Submission never deletes the user or related company data; processing is a separate admin action.",
  "properties": {
    "creation_key": {
      "type": "string",
      "description": "Deterministic one-record-per-authorized-user identity for idempotent request submission"
    },
    "authorized_email_id": {
      "type": "string",
      "description": "AuthorizedEmail record ID for the signed-in requester"
    },
    "user_email": {
      "type": "string",
      "description": "Normalized email of the signed-in requester at submission time"
    },
    "user_name": {
      "type": "string",
      "description": "Display name of the signed-in requester at submission time"
    },
    "status": {
      "type": "string",
      "enum": [
        "pending",
        "processed",
        "cancelled"
      ],
      "default": "pending",
      "description": "Administrative processing state; submission only creates pending requests"
    },
    "requested_at": {
      "type": "string",
      "format": "date-time",
      "description": "When the requester submitted the deletion review request"
    },
    "processed_at": {
      "type": "string",
      "format": "date-time",
      "description": "When an administrator later resolved the request"
    },
    "processed_by": {
      "type": "string",
      "description": "Administrator email that later resolved the request"
    },
    "resolution_source_updated_date": {
      "type": "string",
      "description": "Pending record version used for the administrator's conditional resolution; supports safe duplicate retries."
    },
    "admin_notes": {
      "type": "string",
      "description": "Administrative processing notes"
    }
  },
  "required": [
    "creation_key",
    "authorized_email_id",
    "user_email",
    "status",
    "requested_at"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__account_deletion_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__account_deletion_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__account_deletion_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__account_deletion_backend_only__"
      }
    }
  }
}

{
  "name": "ActivityLog",
  "type": "object",
  "properties": {
    "work_order_id": {
      "type": "string",
      "description": "ID of the related work order"
    },
    "work_order_title": {
      "type": "string",
      "description": "Title of the work order for display"
    },
    "action_type": {
      "type": "string",
      "enum": [
        "work_order_created",
        "work_order_updated",
        "work_order_completed",
        "work_order_deleted",
        "rider_created",
        "stage_changed",
        "note_added",
        "note_deleted",
        "sub_note_added",
        "sub_note_deleted",
        "task_added",
        "task_completed",
        "task_uncompleted",
        "task_deleted",
        "task_edited",
        "image_uploaded",
        "asap_toggled",
        "priority_changed",
        "restored"
      ],
      "description": "Type of action performed"
    },
    "action_details": {
      "type": "string",
      "description": "Human-readable description of the action"
    },
    "previous_value": {
      "type": "string",
      "description": "Previous value before change (if applicable)"
    },
    "new_value": {
      "type": "string",
      "description": "New value after change (if applicable)"
    },
    "performed_by_email": {
      "type": "string",
      "description": "Email of user who performed the action"
    },
    "performed_by_name": {
      "type": "string",
      "description": "Name of user who performed the action"
    }
  },
  "required": [
    "work_order_id",
    "action_type",
    "performed_by_email"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__activitylog_backend_only__" } },
    "read": { "user_condition": { "role": "__activitylog_backend_only__" } },
    "update": { "user_condition": { "role": "__activitylog_backend_only__" } },
    "delete": { "user_condition": { "role": "__activitylog_backend_only__" } }
  }
}

{
  "type": "object",
  "name": "AdminAuditLog",
  "properties": {
    "actor_email": {
      "type": "string"
    },
    "action": {
      "type": "string"
    },
    "target_email": {
      "type": "string"
    },
    "detail": {
      "type": "string"
    },
    "at": {
      "type": "string",
      "format": "date-time"
    }
  },
  "required": [
    "action",
    "at"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "AllInOneEstimate",
  "type": "object",
  "description": "A multifaceted estimate BUILT from sections. Each section is a dedicated sub-estimate created by (and owned by) this estimate in its module's own entity, edited with that module's full estimator INLINE on the same page. Project info (client, estimate #, hyperlink, site address) is shared down to every owned section automatically. Totals live-sync from the source projects via real-time subscriptions and refresh-on-open. Customer pricing waterfall (per-section adjustments \u2192 discount \u2192 contingency \u2192 fees \u2192 tax \u2192 deposit) is computed by components/estimator/allInOne/aioPricing.js. Step 1 fields come from the shared Customer / TaxGroup / EstimateOption entities. Links to the workflow through customer_id (shared Client) and work_order_id.",
  "properties": {
    "project_name": {
      "type": "string",
      "description": "Estimate description shown in Step 1."
    },
    "creation_request_key": {
      "type": "string",
      "description": "Internal random receipt used only to make one New Estimate create action retry-safe. It is not derived from client/project names, so legitimate separate estimates with identical names remain allowed."
    },
    "client_name": {
      "type": "string",
      "description": "Customer company name."
    },
    "customer_id": {
      "type": "string",
      "description": "Linked shared Customer record id."
    },
    "opportunity_id": {
      "type": "string",
      "description": "Optional canonical Opportunity link. Blank is valid for legacy/direct-created Estimates."
    },
    "split_from_estimate_id": {
      "type": "string",
      "description": "Parent estimate id when this estimate was created via Split \u2014 links the child back to its source for traceability."
    },
    "duplicated_from_estimate_id": {
      "type": "string",
      "description": "Source estimate id when this estimate was created via Duplicate \u2014 links the clone back to its source for traceability."
    },
    "estimating_request_id": {
      "type": "string",
      "description": "Optional EstimatingRequest link preserving the pre-estimate handoff identity."
    },
    "work_order_id": {
      "type": "string",
      "description": "Optional linked WorkOrder id \u2014 ties this estimate to a job in the workflow."
    },
    "sales_stage": {
      "type": "string",
      "enum": [
        "lead",
        "quoted",
        "follow_up",
        "won",
        "lost",
        "on_hold"
      ],
      "description": "Mirror of the linked WorkOrder's sales_status, written back when the pipeline stage changes (WorkOrder to estimate reverse sync). Distinct from the estimate lifecycle status field; absent on estimates that were never pipeline-linked."
    },
    "sales_stage_changed_at": {
      "type": "string",
      "format": "date-time",
      "description": "Timestamp of the most recent sales_stage write-back from the linked WorkOrder."
    },
    "estimate_number": {
      "type": "string"
    },
    "po_number": {
      "type": "string",
      "description": "Customer purchase order number, shown on the customer quote."
    },
    "delivery_method": {
      "type": "string",
      "enum": [
        "pickup",
        "installation",
        "shipping",
        "delivery"
      ],
      "description": "Requested fulfillment/delivery method captured at quote time (A-28); seeds WorkOrder.fulfillment_method on conversion."
    },
    "terms": {
      "type": "string",
      "description": "Payment terms selected from the admin-managed terms list."
    },
    "order_contact": {
      "type": "string",
      "description": "Contact on the order (from the customer's contacts)."
    },
    "office_phone": {
      "type": "string"
    },
    "office_phone_ext": {
      "type": "string"
    },
    "salesperson": {
      "type": "string"
    },
    "sales_center": {
      "type": "string"
    },
    "tax_group": {
      "type": "string",
      "description": "Name of the selected TaxGroup \u2014 sets tax_percent."
    },
    "hyperlink": {
      "type": "string"
    },
    "site_address": {
      "type": "string",
      "description": "Job site address \u2014 shared down to sections whose module supports it."
    },
    "contact_name": {
      "type": "string"
    },
    "contact_email": {
      "type": "string"
    },
    "contact_phone": {
      "type": "string"
    },
    "target_install_date": {
      "type": "string",
      "description": "Target install/completion date (YYYY-MM-DD)."
    },
    "accepted_at": {
      "type": "string",
      "description": "ISO timestamp of the canonical customer acceptance (mirrors the EstimateAcceptance row)."
    },
    "accepted_by_name": {
      "type": "string",
      "description": "Name recorded on the canonical customer acceptance."
    },
    "accepted_by_email": {
      "type": "string",
      "description": "Email recorded on the canonical customer acceptance."
    },
    "attachment_refs": {
      "type": "array",
      "description": "References to files/photos carried from the opportunity handoff (no binary copies).",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "name": {
            "type": "string"
          },
          "url": {
            "type": "string"
          },
          "source": {
            "type": "string"
          }
        }
      }
    },
    "priority": {
      "type": "string",
      "enum": [
        "low",
        "normal",
        "high",
        "rush"
      ],
      "default": "normal"
    },
    "tags": {
      "type": "string",
      "description": "Comma-separated tags for filtering/search (e.g. 'pylon, rebrand, phase 1')."
    },
    "tax_percent": {
      "type": "number",
      "default": 0,
      "description": "Sales tax % \u2014 tax = taxable base \u00d7 tax%."
    },
    "deposit_percent": {
      "type": "number",
      "default": 50,
      "description": "Deposit % \u2014 deposit = quote total \u00d7 deposit%."
    },
    "discount_percent": {
      "type": "number",
      "default": 0,
      "description": "Project-level discount % applied to the adjusted sections subtotal."
    },
    "contingency_percent": {
      "type": "number",
      "default": 0,
      "description": "Contingency % applied AFTER discount: contingency = (subtotal \u2212 discount) \u00d7 contingency%."
    },
    "shipping_fee": {
      "type": "number",
      "default": 0,
      "description": "Flat project-level shipping/freight fee added before tax."
    },
    "permit_fee": {
      "type": "number",
      "default": 0,
      "description": "Flat project-level permit/admin fee added before tax."
    },
    "round_quote_total": {
      "type": "boolean",
      "default": false,
      "description": "Round the computed quote total to the nearest whole dollar."
    },
    "quote_valid_days": {
      "type": "number",
      "default": 30,
      "description": "How many days the customer quote stays valid."
    },
    "quote_issue_date": {
      "type": "string",
      "format": "date",
      "description": "Customer-facing issue date of the currently issued quote version. Updated when the estimate transitions into sent or when an intentional revision is completed while remaining sent; historical sent estimates are not automatically backfilled."
    },
    "quote_expiration_date": {
      "type": "string",
      "format": "date",
      "description": "Optional per-estimate override of the quote expiration date. When blank, expiry is computed as quote_issue_date + quote_valid_days."
    },
    "quote_expired": {
      "type": "boolean",
      "default": false,
      "description": "Persisted mirror of the computed expiry check (sent past quote_issue_date + quote_valid_days) so expired quotes are reportable by filter without recomputing per row."
    },
    "quote_valid_until": {
      "type": "string",
      "description": "Derived expiry alias read by quote delivery + workspace views (K-10); mirrors quote_expiration_date/computed expiry."
    },
    "email_signature": {
      "type": "string",
      "description": "Per-estimate copy of the QuoteDefaults email signature snapshot for delivery emails (K-10)."
    },
    "email_subject_template": {
      "type": "string",
      "description": "Per-estimate email subject template snapshot (K-10)."
    },
    "email_message_template": {
      "type": "string",
      "description": "Per-estimate email body template snapshot (K-10)."
    },
    "default_tax_group": {
      "type": "string",
      "description": "TaxGroup name resolved for this estimate when no manual tax pick exists (K-10 chain: manual > customer > defaults > TaxGroup.is_default)."
    },
    "signature_text": {
      "type": "string",
      "description": "Print-surface signature block text snapshot (K-10)."
    },
    "disclaimer_text": {
      "type": "string",
      "description": "Print-footer disclaimer line snapshot (K-10)."
    },
    "tax_rate_source": {
      "type": "string",
      "enum": [
        "auto",
        "customer_default",
        "shop_default",
        "group_default",
        "manual",
        "none"
      ],
      "description": "Which hop of the tax-rate resolution chain this estimate used (K-10)."
    },
    "quote_version": {
      "type": "number",
      "default": 0,
      "minimum": 0,
      "description": "Customer-facing quote issue version. Starts at 1 on the first transition into sent and increments on each later transition into sent or completed revision that remains sent. Separate from EstimateRevision.revision_number."
    },
    "payment_terms": {
      "type": "string",
      "description": "Payment terms text shown on the customer quote."
    },
    "scope_inclusions": {
      "type": "string",
      "description": "Newline-separated list of what's INCLUDED \u2014 rendered as bullets on the customer quote."
    },
    "scope_exclusions": {
      "type": "string",
      "description": "Newline-separated list of what's EXCLUDED \u2014 rendered as bullets on the customer quote."
    },
    "scope_auto_apply": {
      "type": "boolean",
      "default": true,
      "description": "When true, scope library lines flagged always_include, or whose auto_modules match a section on this estimate, are added automatically."
    },
    "hide_section_prices": {
      "type": "boolean",
      "default": false,
      "description": "When true the customer quote shows ONE bundled project price instead of per-section pricing."
    },
    "section_acceptance_mode": {
      "type": "boolean",
      "default": false,
      "description": "When true the customer portal lets the customer accept, decline, or question each quote section individually rather than only approving the whole quote."
    },
    "company_name": {
      "type": "string",
      "description": "Your company name shown in the customer quote header."
    },
    "company_phone": {
      "type": "string"
    },
    "company_email": {
      "type": "string"
    },
    "company_address": {
      "type": "string"
    },
    "company_website": {
      "type": "string"
    },
    "company_license": {
      "type": "string",
      "description": "License / registration number printed under the company block."
    },
    "company_logo_url": {
      "type": "string"
    },
    "quote_title": {
      "type": "string",
      "default": "Project Estimate",
      "description": "Headline printed at the top of the quote."
    },
    "quote_accent_color": {
      "type": "string",
      "default": "#4f46e5",
      "description": "Hex accent color for the quote header rule and highlight text."
    },
    "quote_intro_text": {
      "type": "string",
      "description": "Optional paragraph printed above the pricing table."
    },
    "quote_footer_text": {
      "type": "string",
      "description": "Optional paragraph printed at the very bottom of the quote."
    },
    "quote_terms_conditions": {
      "type": "string",
      "description": "Terms & conditions block printed on the quote."
    },
    "warranty_text": {
      "type": "string",
      "description": "Warranty statement printed on the quote."
    },
    "lead_time_text": {
      "type": "string",
      "description": "Production / install lead time statement printed on the quote."
    },
    "show_company_block": {
      "type": "boolean",
      "default": true
    },
    "show_logo": {
      "type": "boolean",
      "default": false
    },
    "show_contact_block": {
      "type": "boolean",
      "default": true
    },
    "show_estimate_number": {
      "type": "boolean",
      "default": true
    },
    "show_po_number": {
      "type": "boolean",
      "default": true
    },
    "show_site_address": {
      "type": "boolean",
      "default": true
    },
    "show_dates": {
      "type": "boolean",
      "default": true
    },
    "show_category_column": {
      "type": "boolean",
      "default": true
    },
    "show_section_descriptions": {
      "type": "boolean",
      "default": true
    },
    "show_quantity_column": {
      "type": "boolean",
      "default": false
    },
    "show_scope_lists": {
      "type": "boolean",
      "default": true
    },
    "show_subtotal_line": {
      "type": "boolean",
      "default": true
    },
    "show_discount_line": {
      "type": "boolean",
      "default": true
    },
    "show_fees_line": {
      "type": "boolean",
      "default": true
    },
    "show_tax_line": {
      "type": "boolean",
      "default": true
    },
    "show_deposit_lines": {
      "type": "boolean",
      "default": true
    },
    "show_notes_on_quote": {
      "type": "boolean",
      "default": false,
      "description": "When true, estimate-level notes are included on the customer quote. Defaults off because estimate notes may contain internal project context."
    },
    "show_terms_block": {
      "type": "boolean",
      "default": true
    },
    "show_warranty_block": {
      "type": "boolean",
      "default": true
    },
    "show_lead_time_block": {
      "type": "boolean",
      "default": true
    },
    "show_signature_block": {
      "type": "boolean",
      "default": true
    },
    "show_validity_footer": {
      "type": "boolean",
      "default": true
    },
    "round_prices_to_dollar": {
      "type": "boolean",
      "default": false,
      "description": "Display-only: rounds every price shown on the customer quote to the nearest dollar."
    },
    "status": {
      "type": "string",
      "enum": [
        "draft",
        "calculated",
        "sent",
        "approved",
        "archived",
        "cancelled"
      ],
      "default": "draft"
    },
    "is_template": {
      "type": "boolean",
      "description": "Marks the estimate as a reusable template \u2014 duplicated into new estimates via the New Estimate template picker."
    },
    "cancel_reason": {
      "type": "string",
      "description": "Reason captured when the estimate is cancelled (from the Cancel Estimate modal)."
    },
    "cancelled_at": {
      "type": "string",
      "format": "date-time",
      "description": "UTC timestamp of the cancellation. The cancelling actor is recorded on the lifecycle EstimateRevision."
    },
    "archived_at": {
      "type": "string",
      "format": "date-time",
      "description": "UTC timestamp the estimate was archived."
    },
    "archived_reason": {
      "type": "string",
      "description": "Optional reason for archiving (e.g. lost, superseded, test, merged)."
    },
    "line_items": {
      "type": "array",
      "description": "Estimate sections. Totals are refreshed from the source projects whenever the estimate is opened, and in real time while it is open.",
      "items": {
        "type": "object",
        "properties": {
          "line_id": {
            "type": "string",
            "description": "Stable id for this estimate product line. Used to link the persistent BuilderProduct record."
          },
          "builder_product_id": {
            "type": "string",
            "description": "Persistent BuilderProduct id for frozen pricing, parts, groups, and full builder snapshots."
          },
          "module_key": {
            "type": "string",
            "description": "Key from the estimator registry (e.g. 'painting', 'foundation')."
          },
          "builder_name": {
            "type": "string",
            "description": "Internal/estimator-facing builder identity or product type."
          },
          "client_product_name": {
            "type": "string",
            "description": "Editable client-facing name for this product; kept distinct from builder_name/project_name."
          },
          "product_category": {
            "type": "string",
            "description": "User-defined Product Category used for estimate organization and customer quote categorization."
          },
          "production_product_type": {
            "type": "string",
            "description": "Optional production/SIP Product Type selected from GlobalSettings.productTypes. Blank means intentionally unclassified."
          },
          "product_notes": {
            "type": "string",
            "description": "Estimator-facing Product notes. Separate from customer_description."
          },
          "project_id": {
            "type": "string"
          },
          "project_name": {
            "type": "string"
          },
          "client_name": {
            "type": "string"
          },
          "total_snapshot": {
            "type": "number",
            "default": 0,
            "description": "Accepted/frozen UNIT Product cost snapshot. Estimate pricing extends this unit amount by customer_quantity, then applies adjustment_percent. Live inventory changes do not replace it until Update Price is accepted."
          },
          "live_total_snapshot": {
            "type": "number",
            "default": 0,
            "description": "Most recently detected/recalculated live cost used only for price-change comparison."
          },
          "price_state": {
            "type": "string",
            "enum": [
              "unchecked",
              "current",
              "changed",
              "detached_parts",
              "legacy_frozen",
              "manual"
            ],
            "default": "unchecked"
          },
          "price_recalc_required": {
            "type": "boolean",
            "default": false,
            "description": "True when Master Inventory changed after this Builder was last calculated and Update Price must wait until the Builder is reopened/saved."
          },
          "price_recalc_reason": {
            "type": "string",
            "description": "Human-readable reason this Product requires Builder recalculation before Update Price."
          },
          "price_acceptance_pending": {
            "type": "object",
            "additionalProperties": true,
